        (function bindScenarioClicks() {
            const items = document.querySelectorAll('.scenario-option');
            items.forEach((el, idx) => {
                const openingId = idx + BASE_INDEX;
                el.dataset.opening = String(openingId);

                el.setAttribute('role', 'button');
                el.setAttribute('tabindex', '0');
                el.setAttribute('aria-label', `切换至开场白 ${openingId}`);

                // 点击切换
                el.addEventListener('click', () => {
                    switchToOpening(openingId);
                });
            });
        })();




